/** Contract-based test harness for the compute entry point
  *
  * @param api_channel1 incoming data port
  * @param api_channel2 incoming data port
  */
pub fn testComputeCB(
  api_channel1: bool,
  api_channel2: bool) -> HarnessResult
{
  // Initialize the app
  crate::actuationSubsystem_saturationActuatorUnit_actuateSaturationActuator_orLogic_initialize();

  // [PutInPorts]: Set values on the input ports
  put_channel1(api_channel1);
  put_channel2(api_channel2);

  // [InvokeEntryPoint]: Invoke the entry point
  crate::actuationSubsystem_saturationActuatorUnit_actuateSaturationActuator_orLogic_timeTriggered();

  // [RetrieveOutState]: retrieve values of the output ports via get operations and GUMBO declared local state variable
  let api_actuate = get_actuate();

  // [CheckPost]: invoke the oracle function
  if !GUMBOX::compute_CEP_Post(api_channel1, api_channel2, api_actuate) {
    return HarnessResult::FailedPostcondition(TestCaseError::Fail("Postcondition failed: incorrect output behavior".into()));
  }

  return HarnessResult::Passed
}

/** Contract-based test harness for the compute entry point
  */
pub fn testComputeCB_container(container: PreStateContainer) -> HarnessResult
{
  return testComputeCB(container.api_channel1, container.api_channel2)
}

